insert into cmn_bank_branch
(
    bank_id,
    mfo,
    branch_type,
    name,
    address,
    opened_date,
    source_updated_date,
    region_id,
    district_id,
    city,
    inn,
    website,
    latitude,
    longitude,
    state_id
)
select
    bank.id,
    source.mfo,
    source.branch_type,
    source.name,
    source.address,
    source.opened_date::date,
    source.source_updated_date::date,
    region.id,
    district.id,
    source.city,
    source.inn,
    source.website,
    source.latitude,
    source.longitude,
    source.state_id
from source_data source
join cmn_bank bank
    on bank.code = source.bank_code
left join lateral
(
    select min(cmn_region.id) as id
    from cmn_region
    where cmn_region.short_name = source.region_name
) region on true
left join lateral
(
    select min(cmn_district.id) as id
    from cmn_district
    where cmn_district.region_id = region.id
      and cmn_district.short_name = source.district_name
) district on true
on conflict (mfo) do update set
    bank_id = excluded.bank_id,
    branch_type = excluded.branch_type,
    name = excluded.name,
    address = excluded.address,
    opened_date = excluded.opened_date,
    source_updated_date = excluded.source_updated_date,
    region_id = excluded.region_id,
    district_id = excluded.district_id,
    city = excluded.city,
    inn = excluded.inn,
    website = excluded.website,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    state_id = excluded.state_id;
